// CERRAR UNA DERIVACION DESDE EL EMAIL (workflow 07, 15-sep-2026)
// El boton "Marcar como atendida" de los emails abre esta direccion con el id
// de la derivacion y su token secreto. Funciona en DOS pasos a proposito:
//   1. Primera visita: solo muestra una pagina de confirmacion.
//   2. Boton "Si, ya le hemos atendido" (misma direccion + &ok=1): la cierra.
// Asi, si el antivirus del correo abre el enlace para analizarlo, no cierra
// nada por su cuenta.
const entrada = $('Recibir enlace').first().json || {};
const q = entrada.query || {};
const id = (q.id || '').toString();
const token = (q.t || '').toString();
const confirmado = (q.ok || '').toString() === '1';

const fila = $('Buscar derivacion').all()
  .map(item => item.json || {})
  .find(r => r.id && r.derivacion_id === id);

// Comparacion que tarda lo mismo acierte o falle: no da pistas sobre el token.
const mismoToken = (a, b) => {
  if (!a || !b || a.length !== b.length) return false;
  let diferencia = 0;
  for (let i = 0; i < a.length; i++) diferencia |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diferencia === 0;
};

const esc = v => (v === null || v === undefined ? '' : v.toString())
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const pagina = (titulo, cuerpo) => '<!doctype html><html lang="es"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title></head>'
  + '<body style="font-family:Arial,Helvetica,sans-serif;background:#f6f7f6;margin:0;padding:24px;color:#222">'
  + '<div style="max-width:480px;margin:40px auto;background:#fff;border-radius:10px;padding:28px;box-shadow:0 1px 4px rgba(0,0,0,.08)">'
  + '<h1 style="font-size:22px;margin:0 0 12px">' + esc(titulo) + '</h1>' + cuerpo + '</div></body></html>';

if (!fila || !mismoToken((fila.token_cierre || '').toString(), token)) {
  return [{ json: { accion: 'mostrar', html: pagina('Enlace no válido', '<p>Este enlace no es válido o está incompleto. Si necesitas cerrar una consulta, avisa a vuestro proveedor del asistente.</p>') } }];
}

const quien = esc(fila.nombre || 'el paciente') + (fila.fecha_hora ? ' (' + esc(fila.fecha_hora) + ')' : '');

if ((fila.estado || '') !== 'pendiente') {
  return [{ json: { accion: 'mostrar', html: pagina('Ya estaba atendida', '<p>La consulta de ' + quien + ' ya estaba marcada como atendida. No hay que hacer nada más.</p>') } }];
}

if (!confirmado) {
  const enlace = '?id=' + encodeURIComponent(id) + '&t=' + encodeURIComponent(token) + '&ok=1';
  return [{
    json: {
      accion: 'mostrar',
      html: pagina('¿Marcar como atendida?',
        '<p>Consulta de <b>' + quien + '</b>.</p>'
        + '<p>Púlsalo solo si ya habéis hablado con el paciente. A partir de ese momento el asistente vuelve a contestarle con normalidad.</p>'
        + '<p style="margin-top:24px"><a href="' + esc(enlace) + '" style="display:inline-block;background:#1a7f5a;color:#fff;padding:12px 18px;border-radius:6px;text-decoration:none;font-weight:bold">Sí, ya le hemos atendido</a></p>')
    }
  }];
}

return [{ json: { accion: 'cerrar', derivacion_id: id, token, quien } }];

// Pagina final despues de intentar cerrar la derivacion.
// Si la actualizacion no devolvio ninguna fila, es que otra persona la cerro
// justo antes (dos clics seguidos, dos personas...).
const decision = $('Decidir').first().json;
const actualizada = $input.all().some(item => item.json && item.json.id);

const pagina = (titulo, cuerpo) => '<!doctype html><html lang="es"><head><meta charset="utf-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1"><title>' + titulo + '</title></head>'
  + '<body style="font-family:Arial,Helvetica,sans-serif;background:#f6f7f6;margin:0;padding:24px;color:#222">'
  + '<div style="max-width:480px;margin:40px auto;background:#fff;border-radius:10px;padding:28px;box-shadow:0 1px 4px rgba(0,0,0,.08)">'
  + '<h1 style="font-size:22px;margin:0 0 12px">' + titulo + '</h1>' + cuerpo + '</div></body></html>';

// decision.quien ya viene escapado desde "Decidir".
const html = actualizada
  ? pagina('Hecho ✅', '<p>La consulta de <b>' + decision.quien + '</b> queda marcada como atendida. El asistente vuelve a contestarle con normalidad.</p><p style="color:#888">Ya puedes cerrar esta página.</p>')
  : pagina('Ya estaba atendida', '<p>Esta consulta ya estaba cerrada. No hay que hacer nada más.</p>');

return [{ json: { html } }];
